```javascript
function getUtcOffset(dateStr: string): number {
  const cached = offsetCache.get(dateStr);
  if (cached !== undefined) return cached;

  const [y, m, d] = dateStr.split('-').map(Number);
  const noon = new Date(Date.UTC(y, m - 1, d, 12, 0, 0));

  const parts = new Intl.DateTimeFormat('en-GB', {
    timeZone: GY_TZ,
    hour: 'numeric',
    hourCycle: 'h23',
  }).formatToParts(noon);

  const localHour = parseInt(parts.find(p => p.type === 'hour')?.value ?? '12', 10);
  const offset = localHour - 12;
  offsetCache.set(dateStr, offset);
  return offset;
}
```

This uses `Intl.DateTimeFormat.formatToParts()` — a browser/Node built-in API. It doesn't do any system calls or I/O. No injection possible here.

