import type { RequestHandler } from './$types';
import { localToUtc } from '@airways/database';

/**
 * Health check: verifies the timezone offset detection used by localToUtc
 * produces correct UTC values for Europe/London during the current season.
 *
 * Expected:
 *   BST (summer): localToUtc('2026-06-15', 10, 30) → 2026-06-15T09:30:00.000Z
 *   GMT (winter): localToUtc('2026-01-15', 10, 30) → 2026-01-15T10:30:00.000Z
 */
export const GET: RequestHandler = async () => {
  const bstTest = localToUtc('2026-06-15', 10, 30);
  const bstOk = bstTest.toISOString() === '2026-06-15T09:30:00.000Z';

  const gmtTest = localToUtc('2026-01-15', 10, 30);
  const gmtOk = gmtTest.toISOString() === '2026-01-15T10:30:00.000Z';

  const ok = bstOk && gmtOk;

  return new Response(JSON.stringify({
    status: ok ? 'ok' : 'degraded',
    bst: { test: '2026-06-15T10:30 Europe/London', expected: '2026-06-15T09:30:00.000Z', actual: bstTest.toISOString(), pass: bstOk },
    gmt: { test: '2026-01-15T10:30 Europe/London', expected: '2026-01-15T10:30:00.000Z', actual: gmtTest.toISOString(), pass: gmtOk },
    checkedAt: new Date().toISOString(),
  }), {
    status: ok ? 200 : 503,
    headers: { 'content-type': 'application/json', 'cache-control': 'no-store' },
  });
};

/** Guernsey timezone - Europe/London (UTC+0 winter, UTC+1 summer/BST) */
export const GY_TZ = 'Europe/London';

/**
 * Returns the current hour (0-23) in Guernsey local time.
 * @param d - Date to get the hour for (defaults to now)
 * @returns Hour as a number (0-23)
 */
export function guernseyHour(d: Date = new Date()): number {
  return parseInt(
    new Intl.DateTimeFormat('en-GB', { timeZone: GY_TZ, hour: 'numeric', hour12: false }).format(d),
    10,
  );
}

/**
 * Returns the current date as YYYY-MM-DD in Guernsey local time.
 * @param d - Date to format (defaults to now)
 * @returns Date string in en-CA format (YYYY-MM-DD)
 */
export function guernseyDateStr(d: Date = new Date()): string {
  return new Intl.DateTimeFormat('en-CA', { timeZone: GY_TZ }).format(d);
}

/**
 * Returns tomorrow's date string (YYYY-MM-DD) in Guernsey local time.
 * Adds 1 day in UTC first, then converts — correctly handles BST boundary.
 * @returns Tomorrow's date as YYYY-MM-DD
 */
export function guernseyTomorrowStr(): string {
  const tomorrow = new Date();
  tomorrow.setUTCDate(tomorrow.getUTCDate() + 1);
  return new Intl.DateTimeFormat('en-CA', { timeZone: GY_TZ }).format(tomorrow);
}

/**
 * Returns the next UTC Date at which Guernsey local time will be `hour:minute`.
 * If that time today is already past, returns tomorrow's occurrence.
 * @param hour - Target hour (0-23)
 * @param minute - Target minute (0-59)
 * @returns The next UTC Date matching the specified Guernsey local time
 */
export function nextGuernseyTime(hour: number, minute: number): Date {
  const todayGY = guernseyDateStr();
  const pad = (n: number) => String(n).padStart(2, '0');
  const candidateStr = `${todayGY}T${pad(hour)}:${pad(minute)}:00`;

  const now = new Date();
  const nowGYStr = new Intl.DateTimeFormat('en-GB', {
    timeZone: GY_TZ,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: false,
  }).format(now);

  // en-GB format: "DD/MM/YYYY, HH:MM:SS"
  const [datePart, timePart] = nowGYStr.split(', ');
  const [dd, mm, yyyy] = datePart.split('/');
  const gyWallNow = new Date(`${yyyy}-${mm}-${dd}T${timePart}Z`); // treat as UTC for arithmetic
  const offsetMs = now.getTime() - gyWallNow.getTime();

  const targetGYWall = new Date(`${candidateStr}Z`);
  let targetUTC = new Date(targetGYWall.getTime() + offsetMs);

  if (targetUTC <= now) {
    targetUTC = new Date(targetUTC.getTime() + 24 * 60 * 60 * 1000);
  }

  return targetUTC;
}

/**
 * Shared time formatting utilities — always uses Guernsey local time (Europe/London).
 * Import from $lib/time instead of using raw toLocaleTimeString/DateString directly.
 */

export const GY_TZ = 'Europe/London';

/** Format a date/time as HH:MM in Guernsey local time. */
export function formatGuernseyTime(date: string | Date | null | undefined): string {
  if (!date) return '--:--';
  return new Date(date).toLocaleTimeString('en-GB', {
    hour: '2-digit',
    minute: '2-digit',
    timeZone: GY_TZ,
  });
}

/** Format a date/time as "DD Mon YYYY, HH:MM" in Guernsey local time. */
export function formatGuernseyDateTime(date: string | Date | null | undefined): string {
  if (!date) return '—';
  return new Date(date).toLocaleString('en-GB', {
    day: '2-digit',
    month: 'short',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
    timeZone: GY_TZ,
  });
}

/** Format a date as "Day, DD Mon" in Guernsey local time. */
export function formatGuernseyShortDate(date: string | Date | null | undefined): string {
  if (!date) return '';
  return new Date(date).toLocaleDateString('en-GB', {
    weekday: 'short',
    day: 'numeric',
    month: 'short',
    timeZone: GY_TZ,
  });
}

/** Format a date as "DD Mon YYYY" (e.g., "07 Jun 2026") — stats page date display. */
export function formatDate(date: string | Date | null | undefined): string {
  if (!date) return '';
  return new Date(date).toLocaleDateString('en-GB', {
    day: '2-digit',
    month: 'short',
    year: 'numeric',
    timeZone: GY_TZ,
  });
}

